+}
+add_action('after_setup_theme', 'akvadom22_setup');
+
+function akvadom22_assets(): void
+{
+  $theme_version = wp_get_theme()->get('Version');
+  wp_enqueue_style('akvadom22-style', get_stylesheet_uri(), [], $theme_version);
+}
+add_action('wp_enqueue_scripts', 'akvadom22_assets');
+
+function akvadom22_get_phone_href(string $phone): string
+{
+  $digits = preg_replace('/\D+/', '', $phone);
+  if ($digits === null) {
+    $digits = '';
+  }
+  return 'tel:+' . ltrim($digits, '+');
+}
